// Exact generated instance membership can be used by network allowlists.
// The broader routing heuristic below is not proof of a Mastodon server.
export function isKnownMastodonHost(hostname) {
  return KNOWN_MASTODON_HOSTS.has(String(hostname || '').toLowerCase());
}

// Keep direct URL matching conservative: bare /@user and /users/user routes are
// only Mastodon when the host is in the generated known-instance list.
export function isLikelyMastodonHost(hostname) {
  const host = normalizedHostname(hostname);
  return KNOWN_MASTODON_HOSTS.has(host) || host.startsWith('mastodon.');
}

function isMastodonAppPath(hostname, path) {
  return isLikelyMastodonHost(hostname)
    && /^\/(?:home|deck|web|notifications|explore|public|public\/local|settings|lists|publish|start|get-started|get-started\/profile|getting-started)(?:\/|$)/i.test(path);
}

// The web app's other columns (Favourites, Bookmarks, ...) are the same
// Mastodon app as Home: its adapter notes, publication receipts and native
// post handling follow a task there too, for example a reply started from
// Favourites. isMastodonUrl keeps its narrower list for the page observers
// (isMastodonPageUrl) and the finance-site exclusion.
function isMastodonAdapterUrl(url) {
  if (isMastodonUrl(url)) return true;
  const u = new URL(url);
  return /^https?:$/.test(u.protocol) && isLikelyMastodonHost(u.hostname)
    && /^\/(?:favourites|bookmarks|conversations|followed_tags|pinned|directory|follow_requests|mutes|blocks|domain_blocks|search|tags)(?:\/|$)/i.test(safeDecodePath(u.pathname));
}

function isMastodonLocalProfilePath(hostname, path) {
  return isLikelyMastodonHost(hostname) && /^\/@[A-Za-z0-9_]+\/?$/.test(path);
}

function isMastodonUsersPath(hostname, path) {
  const match = /^\/users\/[A-Za-z0-9_]+(\/statuses\/[A-Za-z0-9._:-]+)?\/?$/.exec(path);
  if (!match) return false;
  return Boolean(match[1]) || isLikelyMastodonHost(hostname);
}

function isMastodonRemoteUsersPath(path) {
  return /^\/users\/[A-Za-z0-9_]+(?:\/statuses\/[A-Za-z0-9._:-]+)?\/?$/.test(path);
}

function isMastodonRemoteUri(value) {
  const raw = String(value || '').trim();
  if (/^acct:[A-Za-z0-9_]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/i.test(raw)) return true;
  try {
    const remote = new URL(raw);
    if (remote.protocol !== 'http:' && remote.protocol !== 'https:') return false;
    const path = safeDecodePath(remote.pathname);
    return /^\/@[A-Za-z0-9_]+(?:@[A-Za-z0-9.-]+\.[A-Za-z]{2,})?(?:\/\d+)?\/?$/.test(path)
      || isMastodonRemoteUsersPath(path);
  } catch (e) {
    return false;
  }
}

function hasMastodonInteractionSignal(url, path) {
  return /^\/(interact|authorize_interaction)\/?$/.test(path)
    && isMastodonRemoteUri(url.searchParams.get('uri'));
}

// Whether a page is a Mastodon instance's own page, by its address: a known
// or mastodon.* instance's app, profile or status routes, a remote account's
// profile (/@user@host), or the remote interaction routes.
export function isMastodonPageUrl(url) {
  try { return isMastodonUrl(url); } catch { return false; }
}

function isMastodonUrl(url) {
  const u = new URL(url);
  if (u.protocol !== 'http:' && u.protocol !== 'https:') return false;
  const path = safeDecodePath(u.pathname);
  return isMastodonLocalProfilePath(u.hostname, path)
    || isMastodonAppPath(u.hostname, path)
    || /^\/@[A-Za-z0-9_]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}(?:\/\d+)?\/?$/.test(path)
    || /^\/@[A-Za-z0-9_]+(?:@[A-Za-z0-9.-]+\.[A-Za-z]{2,})?\/\d+\/?$/.test(path)
    || isMastodonUsersPath(u.hostname, path)
    || hasMastodonInteractionSignal(u, path);
}

function isDirectBaiduSearchUrl(url) {
  let parts;
  try {
    parts = adapterUrlParts(url);
  } catch (e) {
    return false;
  }
  if (!parts) return false;
  const host = parts.parsed.hostname.toLowerCase();
  const { path } = parts;
  if (host === 'baidu.com' || host === 'www.baidu.com') {
    return path === '/' || /^\/(?:s|link)(?:\/|$)/.test(path);
  }
  if (host === 'm.baidu.com') return path === '/' || /^\/s(?:\/|$)/.test(path);
  if (host === 'image.baidu.com') return path === '/' || /^\/search(?:\/|$)/.test(path);
  if (host === 'video.baidu.com') return path === '/' || /^\/v(?:\/|$)/.test(path);
  return host === 'news.baidu.com' && /^\/ns(?:\/|$)/.test(path);
}

function isDirectBaiduTiebaUrl(url) {
  let parts;
  try {
    parts = adapterUrlParts(url);
  } catch (e) {
    return false;
  }
  return Boolean(parts) && normalizedHostname(parts.parsed.hostname) === 'tieba.baidu.com';
}

function isBaiduTiebaUrl(url) {
  if (isDirectBaiduTiebaUrl(url)) return true;
  let parts;
  try {
    parts = adapterUrlParts(url);
  } catch (e) {
    return false;
  }
  if (!parts) return false;
  const host = parts.parsed.hostname.toLowerCase();
  if (host !== 'passport.baidu.com' && host !== 'wappass.baidu.com') return false;
  const targets = [];
  for (const param of ['backurl', 'u']) {
    targets.push(...parts.parsed.searchParams.getAll(param));
  }
  return targets.length > 0 && targets.every(isDirectBaiduTiebaUrl);
}

function isBaiduSearchUrl(url) {
  if (isDirectBaiduSearchUrl(url)) return true;
  let parts;
  try {
    parts = adapterUrlParts(url);
  } catch (e) {
    return false;
  }
  if (!parts) return false;
  const host = parts.parsed.hostname.toLowerCase();
  if (host !== 'passport.baidu.com' && host !== 'wappass.baidu.com') return false;
  const targets = [];
  for (const param of ['backurl', 'u']) {
    targets.push(...parts.parsed.searchParams.getAll(param));
  }
  return targets.length > 0 && targets.every(isDirectBaiduSearchUrl);
}

function applicationWorkflowJobs() {
  return {
    'prepare-application': {
      description: 'Fill and review an application without submitting it.',
      template: 'form',
      stateChange: true,
      requiresSubmission: false,
      requiresLedger: true,
      stages: ['access_gate', 'inventory', 'fill', 'review', 'reconcile', 'verify'],
      successEvidence: ['Every requested field is reconciled against supplied information and the application remains unsubmitted.'],
      partialEvidence: ['Completed, unresolved, and intentionally unanswered fields plus the exact blocker are reported.'],
    },
    'submit-application': {
      description: 'Fill, review, submit, and verify an application.',
      template: 'form',
      stateChange: true,
      requiresSubmission: true,
      requiresLedger: true,
      stages: ['access_gate', 'inventory', 'fill', 'review', 'reconcile', 'commit', 'verify'],
      successEvidence: ['A post-submit confirmation, receipt, or application identifier is visible for the intended role.'],
      partialEvidence: ['Completed, unresolved, and intentionally unanswered fields plus the exact submission blocker are reported.'],
    },
  };
}

